INSERT OR IGNORE INTO courses (id,slug,title,description,created_at,updated_at) VALUES ('pilot-course-1','seu-primeiro-curriculo','Seu primeiro currículo','Transforme sua trajetória real em um currículo claro, mesmo sem experiência formal. Duas aulas curtas com prática e perguntas.','2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT OR IGNORE INTO course_versions (id,course_id,version,pass_score,created_at) VALUES ('pilot-course-1-v1','pilot-course-1',1,70,'2026-09-20T00:00:00.000Z');
INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('pilot-course-1-v1-m0','pilot-course-1-v1','Da sua história ao currículo',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,position) VALUES ('pilot-course-1-v1-m0-l0','pilot-course-1-v1-m0','Reconheça o que você já fez','[{"title":"Experiência vai além da carteira assinada","text":"Um currículo organiza fatos relevantes para uma oportunidade. Projetos escolares, voluntariado, trabalho informal e ajuda em um negócio familiar podem mostrar habilidades reais. Explique o contexto sem apresentar essas atividades como um emprego que não existiu.\n\nExemplo: ‘Apoiei a organização dos produtos na loja da família’ é mais claro e fiel do que inventar um cargo de gerência."},{"title":"Conecte a atividade à sua contribuição","text":"Escolha uma atividade e responda: o que precisava ser feito, o que eu fiz e o que observei ou aprendi? Use verbos concretos: organizei, conferi, atendi, registrei. Só mencione resultados e números que você conhece.\n\nFaça uma anotação: atividade / minha contribuição / aprendizado. Isso será matéria-prima para sua experiência ou projeto no currículo."},{"title":"Selecione o que combina com a vaga","text":"Leia as tarefas da vaga e destaque experiências verdadeiras relacionadas. Para atendimento, por exemplo, escuta e organização de pedidos podem ser relevantes. Não transforme vontade de aprender uma ferramenta em domínio dessa ferramenta.\n\nFormação, cursos concluídos e habilidades em desenvolvimento devem aparecer com seu estado real. Se não sabe uma data, confirme antes de preencher."}]',0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-1-v1-m0-l0-q0','pilot-course-1-v1-m0-l0','single_choice','Você ajudou a organizar produtos na loja da família. Como apresentar isso?','Descreva a atividade real e sua contribuição. Experiência informal é válida sem inventar vínculo, cargo ou resultado.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l0-q0-o0','pilot-course-1-v1-m0-l0-q0','Dizer que foi gerente para valorizar o currículo',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l0-q0-o1','pilot-course-1-v1-m0-l0-q0','Descrever o apoio à organização dos produtos como atividade informal',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l0-q0-o2','pilot-course-1-v1-m0-l0-q0','Omitir tudo porque não havia carteira assinada',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-1-v1-m0-l0-q1','pilot-course-1-v1-m0-l0','reflection','Conte uma atividade real e qual foi sua contribuição. Pode ser algo da escola, família ou comunidade.','Revise sua resposta: ela informa o contexto e o que você fez? Evite atribuir a si o trabalho de outras pessoas. Não é necessário ter um resultado numérico.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,position) VALUES ('pilot-course-1-v1-m0-l1','pilot-course-1-v1-m0','Organize e revise antes de enviar','[{"title":"Comece pelo essencial","text":"Use nome, cidade, um meio de contato que você acompanha e objetivo profissional. Endereço completo, números de documentos e informações sensíveis não são necessários para descrever suas qualificações.\n\nSepare resumo, experiências ou projetos, formação, cursos, habilidades e idiomas. Priorize a leitura clara e escolha um dos modelos disponíveis no editor."},{"title":"Escreva para facilitar a leitura","text":"Prefira frases objetivas e organize experiências mais recentes primeiro quando souber as datas. Em vez de ‘sou excelente em tudo’, mostre atividades que sustentem suas habilidades.\n\nSe usar IA, leia cada seção e confira cargos, empresas, datas e competências. Uma sugestão bem escrita ainda pode conter erros. Você decide o que entra no documento."},{"title":"Faça sua revisão final","text":"Confira os contatos, a ortografia, as datas e se o arquivo abre corretamente. Compare o conteúdo com a vaga, mantendo apenas fatos verdadeiros. Veja a prévia de impressão antes de salvar em PDF.\n\nNenhum modelo garante aprovação em sistemas de seleção ou contratação. Um currículo claro ajuda a comunicar sua trajetória, mas o processo depende de vários fatores."}]',1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-1-v1-m0-l1-q0','pilot-course-1-v1-m0-l1','multiple_choice','O que deve fazer parte da revisão final? Selecione todas as alternativas adequadas.','Revisar contatos e confirmar fatos ajuda a evitar erros. A IA não substitui sua conferência e documentos pessoais não melhoram a descrição de qualificações.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l1-q0-o0','pilot-course-1-v1-m0-l1-q0','Verificar se os contatos estão corretos',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l1-q0-o1','pilot-course-1-v1-m0-l1-q0','Confirmar fatos, datas e competências sugeridos pela IA',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l1-q0-o2','pilot-course-1-v1-m0-l1-q0','Aceitar qualquer sugestão da IA sem ler',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-1-v1-m0-l1-q0-o3','pilot-course-1-v1-m0-l1-q0','Adicionar números de documentos ao currículo',0,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-1-v1-m0-l1-q1','pilot-course-1-v1-m0-l1','reflection','Qual parte do seu currículo você precisa conferir antes de enviar? Defina uma ação concreta.','Uma ação pequena e verificável ajuda: confirmar uma data, revisar o e-mail ou conferir a prévia em PDF. Use o editor para colocar essa ação em prática.',1);
INSERT OR IGNORE INTO courses (id,slug,title,description,created_at,updated_at) VALUES ('pilot-course-2','prepare-se-para-entrevista','Prepare-se para a entrevista','Pratique sua apresentação e organize exemplos reais para conversar sobre suas experiências com clareza.','2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT OR IGNORE INTO course_versions (id,course_id,version,pass_score,created_at) VALUES ('pilot-course-2-v1','pilot-course-2',1,70,'2026-09-20T00:00:00.000Z');
INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('pilot-course-2-v1-m0','pilot-course-2-v1','Preparação e conversa',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,position) VALUES ('pilot-course-2-v1-m0-l0','pilot-course-2-v1-m0','Apresente sua trajetória com clareza','[{"title":"Entenda a oportunidade","text":"Releia a descrição da vaga e identifique as principais tarefas. Consulte as informações públicas da organização e anote o que gostaria de entender melhor. Não é necessário conhecer todas as respostas.\n\nPrepare dois exemplos reais que tenham relação com as atividades da vaga. Eles podem vir de trabalho, estudo, projeto ou voluntariado."},{"title":"Responda ‘fale sobre você’","text":"Uma apresentação pode conectar três pontos: seu momento atual, uma experiência relevante e o que busca no próximo passo. Mantenha o foco profissional sem decorar um discurso.\n\nExemplo de estrutura: ‘Estou concluindo… Em uma atividade recente, contribuí com… Procuro uma oportunidade para…’. Complete apenas com informações verdadeiras."},{"title":"Pratique em voz alta","text":"Anote três ideias-chave e pratique uma resposta curta. Observe se a fala está clara e se há termos que precisam de contexto. Você pode pedir a alguém de confiança que diga o que entendeu.\n\nPrepare também horário, trajeto ou conexão, ambiente para uma chamada e um meio de contato. Se precisar de alguma adaptação para participar, busque o canal informado no processo."}]',0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-2-v1-m0-l0-q0','pilot-course-2-v1-m0-l0','single_choice','Qual preparação ajuda a responder ‘fale sobre você’?','Ideias-chave e exemplos reais ajudam a conversar com naturalidade. Decorar um discurso longo pode dificultar a adaptação à pergunta.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l0-q0-o0','pilot-course-2-v1-m0-l0-q0','Memorizar um texto longo sem relação com a vaga',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l0-q0-o1','pilot-course-2-v1-m0-l0-q0','Conectar momento atual, experiência relevante e próximo passo',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l0-q0-o2','pilot-course-2-v1-m0-l0-q0','Inventar experiência para preencher o tempo',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-2-v1-m0-l0-q1','pilot-course-2-v1-m0-l0','reflection','Escreva as três ideias que você gostaria de transmitir na sua apresentação.','Confira se suas ideias mostram seu momento, uma contribuição real e o que procura. Não é preciso incluir informações íntimas ou sensíveis.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,position) VALUES ('pilot-course-2-v1-m0-l1','pilot-course-2-v1-m0','Conte exemplos e faça perguntas','[{"title":"Contexto, ação e resultado","text":"Para contar sobre um desafio, explique brevemente o contexto, descreva sua ação e diga o resultado observado ou aprendizado. Deixe claro o que foi sua contribuição e o que foi realizado pela equipe.\n\nUm resultado pode ser qualitativo: uma tarefa organizada, uma dúvida resolvida, uma forma melhor de trabalhar. Não invente porcentagens para valorizar a história."},{"title":"Quando você ainda não sabe","text":"Se nunca utilizou uma ferramenta, diga isso com clareza. Você pode mencionar conhecimento relacionado e como pretende aprender, sem apresentar intenção como experiência já adquirida.\n\nSe não entender a pergunta, peça esclarecimento. Uma pausa para organizar a resposta é aceitável; você não precisa responder de imediato."},{"title":"Converse sobre o próximo passo","text":"Prepare perguntas sobre tarefas, rotina, equipe, expectativas e próximas etapas. Escute as respostas e anote o que ajudar na sua decisão. Entrevistas também permitem conhecer melhor a oportunidade.\n\nApós a conversa, registre o que funcionou e o que pode praticar. Essas orientações não garantem contratação; use-as para melhorar sua comunicação e preparação."}]',1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-2-v1-m0-l1-q0','pilot-course-2-v1-m0-l1','multiple_choice','Quais atitudes ajudam a contar um exemplo profissional?','Explicar sua ação e o resultado real permite entender sua contribuição. Quando faltar informação, reconheça a limitação em vez de inventar.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l1-q0-o0','pilot-course-2-v1-m0-l1-q0','Explicar o contexto e minha ação',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l1-q0-o1','pilot-course-2-v1-m0-l1-q0','Mencionar o resultado observado ou aprendizado',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l1-q0-o2','pilot-course-2-v1-m0-l1-q0','Atribuir a mim tudo o que a equipe fez',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('pilot-course-2-v1-m0-l1-q0-o3','pilot-course-2-v1-m0-l1-q0','Inventar um número quando não sei o resultado exato',0,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('pilot-course-2-v1-m0-l1-q1','pilot-course-2-v1-m0-l1','reflection','Conte um exemplo usando contexto, ação e resultado ou aprendizado. Depois, escreva uma pergunta que faria sobre a vaga.','Confira se o exemplo distingue sua ação da ação de outras pessoas. A pergunta final deve ajudar a entender a oportunidade e pode abordar rotina, expectativas ou próximos passos.',1);
